WITH filtered AS (SELECT *, LOWER(event_type) AS event_type_lower, DATE_TRUNC('month', event_time) AS event_time_period, COALESCE(page, 'UNKNOWN') AS page_filled FROM web_events WHERE page IS NOT NULL) SELECT DATE_TRUNC('WEEK', event_time_period) AS week_start, DATE_TRUNC('QUARTER', event_time) AS quarter_start, BIT_OR(duration_sec) AS duration_sec_bit_or, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, SIZE(COLLECT_SET(page)) AS num_pages, MIN(event_time_period) AS first_event_time_period, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes FROM filtered GROUP BY DATE_TRUNC('WEEK', event_time_period), DATE_TRUNC('QUARTER', event_time);
